"Ahora no":"Not now",
"Ahora se parece al menú Editar de PES 6: barra de título gris carbón, botones y listas como barras plateadas con bordes redondeados, la opción elegida en amarillo dorado y un fondo ámbar desenfocado con luces, estelas y líneas de puntos. Está hecho a mano, sin imágenes del juego.":"Now it looks like the PES 6 Edit menu: charcoal grey title bar, buttons and lists as silver bars with rounded edges, the selected option in golden yellow and a blurred amber background with lights, trails and dotted lines. It's handmade, with no images from the game.",
"Ahora tocá al titular que sale.":"Now tap the starter coming off.",
"Ajustada":"Tight",
"Ajustar":"Adjust",
"Ajuste defensivo extra":"Extra defensive setting",
"Ajustá \"Volumen de los sonidos\" a tu gusto.":"Set \"Sound volume\" to your liking.",
"Ajustá el volumen ahí mismo.":"Adjust the volume right there.",
"Ajustá nivel y contraste, o invertilo.":"Adjust level and contrast, or invert it.",
"Al agregar canciones, el editor lee las etiquetas del archivo (MP3, FLAC y M4A): título, artista, año y la carátula que traen adentro. Si una canción no tiene carátula, se arma una con colores propios, una nota musical y sus iniciales.":"When you add songs, the editor reads the file tags (MP3, FLAC and M4A): title, artist, year and the embedded cover. If a song has no cover, one is made with its own colours, a music note and its initials.",
"Al aplicar cambios de valoración, la nueva cifra aparece con una animación de revelado en lugar de flechas +N, así se ve directamente cómo quedó cada jugador.":"When applying rating changes, the new number appears with a reveal animation instead of +N arrows, so you see right away how each player ended up.",
"Al cambiar opciones de la vista, el 3D se refresca con una transición. Hay vistas fijas (frente, espalda, costados, tres cuartos, arriba, cerca), se puede acercar, mover la cámara y usar el teclado.":"When you change view options, the 3D refreshes with a transition. There are fixed views (front, back, sides, three-quarter, top, close-up), and you can zoom, move the camera and use the keyboard.",
"Al cargar elegís: fotos recortadas de TheSportsDB, una mezcla que completa con fotos de Wikipedia las que falten, o ninguna. Se cambia después en Formación, con la vista Fotos.":"When loading you choose: cut-out photos from TheSportsDB, a mix that fills missing ones with Wikipedia photos, or none. You can change it later in Formation, with the Photos view.",
"Al conectar la carpeta Sider, el editor instala solo el módulo que copia la base del juego, y ahora lee más datos de esa copia.":"When you connect the Sider folder, the editor installs on its own the module that copies the game database, and now reads more data from that copy.",
"Al estar separado, el navegador guarda cada archivo y en las próximas visitas solo baja lo que cambió. La app instalable guarda todos los archivos para funcionar sin internet.":"Since it's split, the browser stores each file and on later visits only downloads what changed. The installable app stores all files to work offline.",
"Al guardar se reconstruye el alfa en la resolución original y se hace una copia de respaldo del archivo anterior.":"Saving rebuilds the alpha at the original resolution and makes a backup of the previous file.",
"Al lado de Apariencia hay un botón 🖥️ Gráficos con el modo gráfico y la calidad. También muestra cuántos cuadros por segundo está dibujando la página y sugiere qué calidad usar.":"Next to Appearance there's a 🖥️ Graphics button with the graphics mode and quality. It also shows how many frames per second the page is drawing and suggests which quality to use.",
"Al pasar de un video de YouTube a otro, el nuevo podía arrancar silenciado o con otro volumen: el navegador silenciaba el segundo reproductor porque no lo habías tocado. Ahora todos los videos suenan en un solo reproductor, con el volumen que elegiste. Entre dos videos el pase es: baja, cambia y sube.":"When going from one YouTube video to another, the new one could start muted or at a different volume: the browser muted the second player because you hadn't touched it. Now all videos play in a single player, at the volume you chose. Between two videos the transition is: fade down, switch, fade up.",
