"Arriba":"Top",
"Arriba de la lista hay dos botones: \"Mi EDIT\" (los jugadores que el EDIT guarda y se editan como siempre) y \"Del juego\" (todos los de la base del juego). Si tu EDIT no tiene jugadores, arranca directo en la base. La pestaña muestra el total de la base, y al pasar el mouse dice cuántos hay en cada lado.":"Above the list there are two buttons: \"My EDIT\" (the players stored in the EDIT, edited as always) and \"From the game\" (everyone in the game database). If your EDIT has no players, it starts straight in the database. The tab shows the database total, and hovering tells you how many there are on each side.",
