"Baja":"Low",
"Baja saca animaciones, desenfoques, sombras y efectos, simplifica la intro y dibuja el 3D a resolución normal: la página anda más liviana en PCs lentas. Media es lo de siempre. Alta sube todo al máximo: el 3D se dibuja con más resolución que la pantalla (supermuestreo), desenfoques y brillos más intensos y más chispas en la intro.":"Low removes animations, blurs, shadows and effects, simplifies the intro and draws the 3D at normal resolution: the page runs lighter on slow PCs. Medium is the usual. High pushes everything to the max: the 3D is drawn at higher resolution than the screen (supersampling), stronger blurs and glows, and more sparks in the intro.",
