"Cada EDIT lleva el usuario de Windows de la PC donde se creó, y el juego rechaza los de otra PC. Para usar este archivo en otra computadora, poné el SID de esa PC (en esa PC:":"Each EDIT carries the Windows user of the PC where it was created, and the game rejects ones from another PC. To use this file on another computer, enter that PC's SID (on that PC:",
"Cada estilo gráfico trae su propia fuente, y la pestaña del navegador estrena ícono.":"Each graphics style brings its own font, and the browser tab gets a new icon.",
"Cada jugador de la base muestra su cara, posición, nacionalidad, edad, altura, valoración, sus equipos con el dorsal (tocá uno para ir al plantel) y todas las habilidades en barras, más pierna mala, estado de forma y resistencia a lesiones. Es lo que usa el juego.":"Each player in the database shows their face, position, nationality, age, height, rating, their teams with shirt number (tap one to go to the squad) and all skills as bars, plus weak foot, form and injury resistance. It's what the game uses.",
"Cada jugador muestra su foto (la misma minicara que usa la Formación) dentro de un círculo con los colores del equipo. Antes solo aparecían si la Formación estaba en modo Fotos y eran muy chicas. Si un jugador no tiene foto, queda la camiseta. Al pasar el mouse por la fila, la foto se agranda un poco.":"Each player shows their photo (the same miniface Formation uses) inside a circle in the team colours. Before, they only showed if Formation was in Photos mode, and they were tiny. If a player has no photo, the shirt stays. Hovering the row makes the photo a bit bigger.",
"Cada jugador respeta su puesto en la formación.":"Each player keeps their position in the formation.",
"Cada modo tiene su versión del logo, sin transparencia ni bordes redondeados, pintada sobre el color real de la barra.":"Each mode has its own version of the logo, with no transparency or rounded corners, painted over the bar's real colour.",
"Cada sección tiene un recuadro de ayuda que se abre y se cierra, con explicaciones más largas. El editor recuerda cuáles dejaste abiertos.":"Each section has a help box that opens and closes, with longer explanations. The editor remembers which ones you left open.",
