"Clásico imita a los editores de escritorio de antes: grises, botones en relieve, sin brillos ni transparencias (tiene versión clara y oscura). Retro está inspirado en los menús de PES de PS2: azul profundo, amarillo, pestañas inclinadas y líneas de TV vieja. Los dos se combinan con la fuente elegida.":"Classic imitates old desktop editors: greys, raised buttons, no glows or transparency (it has light and dark versions). Retro is inspired by the PES menus on PS2: deep blue, yellow, slanted tabs and old TV lines. Both combine with the chosen font.",
