"Con Títulos, Texto y Números y datos elegís dónde se aplica.":"With Titles, Text and Numbers & data you choose where it applies.",
"Con cambios sin guardar":"With unsaved changes",
"Con el reproductor minimizado, el video ahora va arriba de la barra, en el espacio libre de la izquierda, y toma el ancho que haya (mínimo 200 × 200, lo que exige YouTube). Si la pantalla es angosta y no hay hueco, sigue al costado del reproductor para no tapar la lista de equipos.":"With the player minimised, the video now sits above the bar, in the free space on the left, and takes whatever width is available (minimum 200 × 200, as YouTube requires). If the screen is narrow and there's no room, it stays beside the player so it doesn't cover the team list.",
