"Con los botones Títulos, Texto y Números y datos elegís dónde se usa. Abajo ves una vista previa.":"With the Titles, Text and Numbers & data buttons you choose where it's used. There's a preview below.",
"Con los estilos Clásico, Retro o PES 6 Editar, los colores los pone el estilo: Apariencia solo deja cambiar el tamaño de la letra y la cantidad de efectos, y tiene un botón para volver al estilo Moderno.":"With the Classic, Retro or PES 6 Edit styles, the style sets the colours: Appearance only lets you change the text size and the amount of effects, and has a button to go back to the Modern style.",
"Con varios seleccionados en Plantel, \"Equipación…\" cambia mangas, camiseta interior, medias, calzas, camiseta afuera, guantes, color de guantes y botines a todos a la vez.":"With several selected in Squad, \"Kit…\" changes sleeves, undershirt, socks, tights, untucked shirt, gloves, glove colour and boots for all of them at once.",
