"Corte":"Cut",
"Corte pasa directo. Suave baja una canción mientras sube la otra, sin silencio en el medio. Remix funciona como un DJ: a la canción que termina se le cierra el sonido con un filtro y le queda un eco, y la nueva entra sin graves y se va abriendo. La duración del pase se ajusta entre 2 y 14 segundos (cuando tocás \"siguiente\" a mano, el pase dura como máximo 3,5 segundos).":"Cut switches straight away. Smooth fades one song out while the other fades in, with no silence in between. Remix works like a DJ: the ending song gets filtered out with an echo tail, and the new one comes in without bass and gradually opens up. The transition lasts between 2 and 14 seconds (when you hit \"next\" yourself, it lasts 3.5 seconds at most).",
