"Cuando termina de cargar el EDIT, el fondo de la introducción se agranda y se desenfoca mientras se desvanece, la página aparece de a poco y el logo vuela hasta su lugar en la barra.":"When the EDIT finishes loading, the intro background grows and blurs as it fades out, the page fades in and the logo flies to its spot in the bar.",
