"Edad":"Age",
"Edita los kits del juego (content\\kit-server): el config.txt y todas sus texturas. Lo que ves está armado con los modelos reales del juego (camisetas, mangas, 116 cuellos, 16 shorts y medias, sacados del CometKITpreviewer).":"Edits the game's kits (content\\kit-server): config.txt and all its textures. What you see is built with the game's real models (shirts, sleeves, 116 collars, 16 shorts and socks, taken from CometKITpreviewer).",
