"Elegí la carpeta de Sider de tu juego (la que tiene":"Choose your game's Sider folder (the one with",
"Elegí la carpeta de Sider de tu juego: lee kits, caras y nombres de jugadores":"Choose your game's Sider folder: reads kits, faces and player names",
"Elegí otro EDIT00000000 (por ejemplo, uno guardado por el juego después de cambiar una sola cosa) y te muestro qué cambió, con nombres. Sirve para confirmar las opciones marcadas \"sin confirmar\".":"Pick another EDIT00000000 (for example, one saved by the game after changing just one thing) and I'll show you what changed, with names. Useful to confirm options marked \"unconfirmed\".",
