"Elegí un jugador":"Pick a player",
"Elegí un modo: Moderno, Clásico o Retro.":"Pick a mode: Modern, Classic or Retro.",
"Elige el mejor jugador para cada rol de la formación del plan actual":"Picks the best player for each role in the current plan's formation",
"Elige para cada jugada al titular con las mejores habilidades para ella":"Picks the starter with the best skills for each set piece",
"Elástica":"Elastico",
"Emiratos Árabes Unidos":"United Arab Emirates",
"Empatados":"Drawn",
"En \"Fuente de la página\" elegí \"QuickExpress (PES Editor)\", \"QuickExpress con estela en títulos\" (la versión original, con la línea de velocidad en las minúsculas), \"Saira (la anterior)\", otra fuente de tu PC o \"Cargar…\" para usar un archivo.":"In \"Page font\" choose \"QuickExpress (PES Editor)\", \"QuickExpress with trail on titles\" (the original version, with the speed line on lowercase letters), \"Saira (the previous one)\", another font on your PC or \"Load…\" to use a file.",
"En \"Fuente de la página\" elegí una de la lista o tocá \"Cargar…\" y elegí un archivo .ttf, .otf, .woff o .woff2.":"In \"Page font\" pick one from the list or tap \"Load…\" and choose a .ttf, .otf, .woff or .woff2 file.",
"En \"Instrucciones avanzadas\", tocá hasta 2 por lado. Tocá una marcada para quitarla.":"In \"Advanced Instructions\", tap up to 2 per side. Tap a selected one to remove it.",
"En \"Modo gráfico\" elegí \"PES 6 Editar\".":"In \"Graphics mode\" choose \"PES 6 Edit\".",
"En \"Pase entre canciones\" elegí Corte, Suave o Remix.":"In \"Song transition\" choose Cut, Smooth or Remix.",
"En \"🖥️ Gráficos\", \"Sonidos de menú\" elige si suenan solo en PES 6, siempre o nunca.":"In \"🖥️ Graphics\", \"Menu sounds\" chooses whether they play only in PES 6, always or never.",
"En \"🖥️ Gráficos\", \"Sonidos de menú\": \"Solo en PES 6\" (lo normal), \"Siempre\" o \"Nunca\".":"In \"🖥️ Graphics\", \"Menu sounds\": \"Only in PES 6\" (default), \"Always\" or \"Never\".",
"En Estudio de kits abrí la vista del brillo.":"In Kit studio open the gloss view.",
"En PES 6 Editar corre despacio una cinta con novedades, ideas a futuro y datos de la saga, en letra blanca de PES. Al pasar el mouse por un botón o una pestaña, explica qué hace.":"In PES 6 Edit a ticker slowly scrolls news, future ideas and series trivia, in white PES lettering. Hovering over a button or tab explains what it does.",
"En PES 6 Editar y Clásico, con Windows en modo oscuro, el dorsal repetido y las casillas ya no quedan en negro.":"In PES 6 Edit and Classic, with Windows in dark mode, the duplicate shirt number and checkboxes no longer turn black.",
"En algunas instalaciones, el io de Sider no deja crear ni sobrescribir archivos: abrir un archivo para escribir devuelve vacío y sin error (en el sider.log se ve como \"-> nil\", y le pasa también a otros módulos, como PostProcessingEditor y UIColors). La v1.5 lo detecta y en ese caso escribe la copia con las funciones de Windows, por medio del ffi de LuaJIT que el juego ya deja activado (luajit.ext.enabled = 1 en sider.ini). En sider.log queda anotado qué método usó.":"On some installs, Sider's io won't create or overwrite files: opening a file for writing returns nothing and no error (sider.log shows it as \"-> nil\", and it happens to other modules too, like PostProcessingEditor and UIColors). v1.5 detects this and then writes the copy with Windows functions, through LuaJIT's ffi which the game already enables (luajit.ext.enabled = 1 in sider.ini). sider.log records which method was used.",
"En cada casillero de textura tocá cargar y elegí una imagen.":"In each texture slot tap load and pick an image.",
"En el aviso del navegador elegí \"Permitir en cada visita\" para que la próxima vez entre directo.":"In the browser prompt choose \"Allow on every visit\" so it goes straight in next time.",
"En el celular, los temas de YouTube suenan con el reproductor abierto (YouTube no deja ocultar el video). Tus canciones propias suenan siempre.":"On mobile, YouTube tracks play with the player open (YouTube doesn't allow hiding the video). Your own songs always play.",
"En el celular, sin video encima de la página":"On mobile, no video over the page",
"En el estilo PES 6 suenan los sonidos del menú: \"confirmar\" al tocar opciones, pestañas y acciones, y \"deshacer\" al volver, cerrar, apretar Esc o deshacer un cambio (Ctrl+Z).":"In the PES 6 style the menu sounds play: \"confirm\" when tapping options, tabs and actions, and \"cancel\" when going back, closing, pressing Esc or undoing a change (Ctrl+Z).",
"En el panel grande: barra para adelantar o volver, anterior (si el tema ya avanzó más de 4 segundos, vuelve al principio), siguiente, aleatorio, repetir (toda la lista → solo este tema → sin repetir), volumen y silencio. El editor recuerda el volumen, el modo y el último tema que sonó.":"In the big panel: seek bar, previous (if the track is past 4 seconds, it restarts), next, shuffle, repeat (whole list → this track only → no repeat), volume and mute. The editor remembers the volume, the mode and the last track played.",
"En esa carpeta no está sider.ini: elegí la carpeta de Sider (la que tiene sider.exe).":"sider.ini isn't in that folder: choose the Sider folder (the one with sider.exe).",
"En la PC el editor ocupa todo el ancho, la cabecera entra en una sola fila y Apariencia tiene íconos y vistas previas de cada paleta. Las acciones de cada jugador están en el botón ⋯.":"On PC the editor uses the full width, the header fits in one row and Appearance has icons and previews of each palette. Each player's actions are in the ⋯ button.",
"En la cancha":"On the pitch",
"En la carpeta del kit":"In the kit folder",
"En la tabla del plantel, abrí el menú de Acciones del jugador.":"In the squad table, open the player's Actions menu.",
"En la textura del kit (por ejemplo u0100p1), el canal alfa marca cuánto brilla cada parte: blanco brilla más, negro menos. El visor 3D lo aplica como el juego y se puede ver y modificar.":"In the kit texture (for example u0100p1), the alpha channel marks how shiny each part is: white is shinier, black less so. The 3D viewer applies it like the game and you can view and edit it.",
"En la textura del kit el alfa marca cuánto brilla cada parte en el juego: blanco brilla más, negro es mate. {x}":"In the kit texture the alpha marks how shiny each part is in the game: white is shinier, black is matte. {x}",
"En pantallas chicas el video de YouTube no aparece sobre la página: se ve solo con el reproductor abierto. Como YouTube no permite que su audio siga con el video oculto, al cerrar el panel ese tema se pausa y vuelve a sonar al abrirlo. Las canciones propias suenan siempre.":"On small screens the YouTube video doesn't appear over the page: it only shows with the player open. Since YouTube doesn't allow its audio to keep playing with the video hidden, closing the panel pauses that track and it resumes when you open it. Your own songs always play.",
"En sider.log no aparece el módulo edit21_db: Sider no lo cargó. Revisá que en sider.ini esté":"The edit21_db module doesn't appear in sider.log: Sider didn't load it. Check that sider.ini has",
