"Inglaterra":"England",
"Inspirado en el menú Editar de PES 6: barras plateadas, selección amarilla dorada, barra de título gris carbón, fondo ámbar desenfocado y sus sonidos de confirmar y deshacer.":"Inspired by the PES 6 Edit menu: silver bars, golden-yellow selection, charcoal-grey title bar, blurred amber background and its confirm and undo sounds.",
"Inspirado en el modo Editar de PES 6: fondo azul acero con brillos diagonales, barras y botones plateados, línea naranja arriba de cada panel, y la selección (pestaña, equipo o jugador elegido) resaltada con una barra naranja y dorada inclinada. Los títulos van en cursiva.":"Inspired by PES 6 Edit mode: steel-blue background with diagonal highlights, silver bars and buttons, an orange line on top of each panel, and the selection (chosen tab, team or player) highlighted with a slanted orange and gold bar. Titles are in italics.",
"Inspirado en los menús de PES de PS2: azul profundo, amarillo, líneas de TV vieja y esquinas rectas.":"Inspired by the PES menus on PS2: deep blue, yellow, old-TV lines and sharp corners.",
