"La":"The",
"La Estrategia cambia de look en Moderno, Clásico, Retro y PES 6 Editar.":"Strategy gets a new look in Modern, Classic, Retro and PES 6 Edit.",
"La Liga Master es uno de los modos más queridos de PES: armar un equipo desde abajo y llevarlo a la cima.":"Master League is one of the most loved PES modes: build a team from the bottom and take it to the top.",
"La barra de Equipos, Selecciones, Jugadores, etc. es más ancha y usa letra un poco más chica, así entra completa sin tener que desplazarla. En pantallas más angostas se ocultan los avisos de estado para dejar lugar.":"The Teams, National teams, Players, etc. bar is wider and uses a slightly smaller font, so it fits completely without scrolling. On narrower screens the status notices hide to make room.",
"La barra de texto de abajo":"The text bar at the bottom",
"La base del juego no está cargada":"The game database isn't loaded",
"La camiseta, las mangas, más de 100 cuellos, los 16 shorts y las medias salen del CometKIT previewer, con iluminación tipo estadio.":"The shirt, sleeves, 100+ collars, the 16 shorts and the socks come from the CometKIT previewer, with stadium-style lighting.",
"La cara y el pelo no se editan acá: se conservan como están.":"Face and hair aren't edited here: they're kept as they are.",
"La carga te pide Sider":"Loading asks for Sider",
"La carpeta Sider y la base del juego":"The Sider folder and the game database",
"La carpeta WEPES está vacía.":"The WEPES folder is empty.",
"La clave de API-Football no es válida.":"The API-Football key isn't valid.",
"La columna \"Cap.\" se reemplazó: el capitán se elige en el menú de la columna Acciones de cada jugador, y se marca con una \"C\" al lado de su nombre.":"The \"Cap.\" column was replaced: pick the captain from the Actions column menu of each player, and they get a \"C\" next to their name.",
"La columna Nación muestra la bandera de verdad del país. Las fotos son más grandes y su borde y fondo cambian según la posición: arquero, defensa, medio o delantero.":"The Nation column shows the country's real flag. Photos are bigger and their border and background change by position: goalkeeper, defender, midfielder or forward.",
"La copia de la base del juego está incompleta: faltan":"The copy of the game database is incomplete: missing",
"La copia de la base ya se guarda y el video va arriba del reproductor":"The database copy now saves and the video goes above the player",
"La del estilo: {x}":"The style's one: {x}",
"La descripción, el logo o el SID no coinciden con los del editor.":"The description, logo or SID don't match the editor's.",
"La fuente de estilo PES pasó a ser la de toda la página. Se reparó (Chrome la rechazaba por un error interno del archivo), se le agregaron las letras que faltaban para el español y para nombres de jugadores (á, é, í, ó, ú, ñ, ü, ö, à, ã, ç, ¿, ¡, comillas, coma) y se angostó al 80 % para que entre bien en botones y pestañas. Se puede seguir cambiando.":"The PES-style font is now the font for the whole page. It was fixed (Chrome rejected it because of an internal file error), the missing characters for Spanish and player names were added (á, é, í, ó, ú, ñ, ü, ö, à, ã, ç, ¿, ¡, quotes, comma) and it was narrowed to 80 % so it fits nicely in buttons and tabs. You can still change it.",
"La fuente se elige por estilo: lo que cambies en Retro queda para Retro, y lo de Moderno para Moderno. QuickExpress sigue disponible en todos.":"The font is chosen per style: what you change in Retro stays in Retro, and Modern's stays in Modern. QuickExpress is still available in all of them.",
"La lista de la selección. Los convocados siguen en sus clubes: convocar no los saca de ningún plantel.":"The national team list. Called-up players stay at their clubs: calling them up doesn't remove them from any squad.",
"La línea defensiva se queda atrás para cubrir el espacio a su espalda.":"The defensive line stays back to cover the space behind it.",
"La maqueta plana del kit se corrigió y se sumó el visor 3D.":"The flat kit mockup was fixed and the 3D viewer was added.",
"La música arranca cuando toques algo en la página":"Music starts when you touch something on the page",
"La música pasó a tener su propio reproductor fijo abajo a la izquierda, con cinco temas de menú de PES de la época de PS2.":"Music now has its own fixed player at the bottom left, with five PES menu tracks from the PS2 era.",
"La pantalla de carga se volvió más llamativa y se agregó esta sección.":"The loading screen got flashier and this section was added.",
"La pestaña Formación usa las mismas opciones y nombres que el Plan de juego de PES 2021, con su explicación, y suma el capitán y los lanzadores de balón parado. Todo verificado en el juego.":"The Formation tab uses the same options and names as the PES 2021 Game Plan, with their explanations, and adds the captain and set-piece takers. All verified in-game.",
"La pestaña Jugadores ya no muestra solo los que están en tu EDIT: con la base del juego copiada, se ven los más de 27.000 jugadores del juego.":"The Players tab no longer shows only the ones in your EDIT: with the game database copied, you see the game's 27,000+ players.",
"La pestaña del navegador muestra el logo PES con un borde oscuro, para que se vea tanto con el navegador en modo claro como en oscuro.":"The browser tab shows the PES logo with a dark border, so it looks good with the browser in both light and dark mode.",
"La primera vez":"The first time",
"La primera vez tocá \"📂 Elegir mi carpeta Documentos\". La ventana ya se abre en Documentos: solo tocá \"Seleccionar carpeta\".":"The first time, tap \"📂 Choose my Documents folder\". The window already opens in Documents: just tap \"Select folder\".",
"La página estrena fuente, se pueden elegir modos y calidad gráfica, y el reproductor suma carátulas automáticas y listas de YouTube.":"The page gets a new font, you can pick graphics modes and quality, and the player adds automatic covers and YouTube playlists.",
"La versión pública no trae los temas de los menús de PES por derechos de autor. El reproductor funciona igual: cada uno agrega sus canciones y carátulas, que quedan guardadas en su navegador.":"The public version doesn't include the PES menu tracks for copyright reasons. The player works the same: everyone adds their own songs and covers, which stay saved in their browser.",
