"Largo de cuello":"Neck length",
"Largo de piernas":"Leg length",
"Las 4 instrucciones avanzadas":"The 4 advanced instructions",
"Las del juego (Balones largos a la contra, Contraataques rápidos, Juego de posesión, Defensa total, Todos adelante, Por las bandas y Por el centro) cambian varias opciones de una vez. Los valores son aproximados porque el juego no los guarda en el EDIT.":"The game's ones (Long Ball Counter, Quick Counter, Possession Game, Total Defence, All-out Attack, Out Wide and Down the Middle) change several options at once. Values are approximate because the game doesn't store them in the EDIT.",
"Las letras A a Z y el punto del nombre en la espalda.":"The letters A to Z and the dot for the name on the back.",
"Las letras y números se ubican en las mismas casillas que las plantillas de Photoshop (Letters / Numbers Template), con fondo transparente, como las espera el juego.":"Letters and numbers sit in the same cells as the Photoshop templates (Letters / Numbers Template), with a transparent background, as the game expects.",
"Las partes del modelo (cuerpo, mangas, cuello y short) comparten las normales en los bordes, así no se ven cortes ni cambios de luz en las uniones.":"The model parts (body, sleeves, collar and shorts) share normals at the edges, so there are no seams or lighting changes at the joins.",
"Las versiones se numeran v0.0NN y cada una muestra fecha y hora. Cada cambio tiene explicación y, cuando hace falta, los pasos para usarlo. Hay buscador, filtros por tema y \"Abrir todo / Cerrar todo\".":"Versions are numbered v0.0NN and each one shows date and time. Every change has an explanation and, when needed, the steps to use it. There's a search box, topic filters and \"Expand all / Collapse all\".",
