"Logo para modo claro y oscuro":"Logo for light and dark mode",
"Logo, cabecera nueva y fuente propia":"Logo, new header and custom font",
"Los 10 números (0 a 9) de la espalda.":"The 10 numbers (0 to 9) on the back.",
"Los colores":"The colours",
"Los controles de luz se rediseñaron, hay una esfera para mover la dirección del sol y se puede cargar un fondo HDRI propio que también ilumina la camiseta.":"Light controls were redesigned, there's a sphere to move the sun direction and you can load your own HDRI background that also lights the shirt.",
"Los datos descifrados no coinciden con los del editor.":"The decrypted data doesn't match the editor's.",
"Los datos salen de":"Data comes from",
"Los de banda bajan a defender su costado como carrileros.":"Wide players drop back to defend their flank like wing-backs.",
"Los delanteros presionan desde arriba para recuperar la pelota cuanto antes.":"Forwards press high to win the ball back as soon as possible.",
"Los jugadores de banda intercambian posiciones para desordenar la marca.":"Wide players swap positions to unsettle the marking.",
"Los jugadores de banda juegan pegados a la línea lateral para abrir la defensa rival.":"Wide players hug the touchline to stretch the opposing defence.",
"Los jugadores esperan, cubren espacios y no se arriesgan a quedar desparramados.":"Players wait, cover spaces and don't risk being caught out of shape.",
"Los jugadores quedaron desordenados por ID.":"Players are now out of order by ID.",
"Los jugadores salen con decisión a quitarle la pelota al rival.":"Players go in hard to win the ball from the opponent.",
