"Moderno":"Modern",
"Moderno usa Outfit para el texto y Big Shoulders para los títulos: modernas y fáciles de leer. PES 6 Editar usa QuickExpress, la del estilo PES. Retro usa Pixelify Sans y Silkscreen, letras de píxeles inspiradas en los Winning Eleven de PlayStation 1 pero legibles. Clásico usa Tahoma, como los programas de escritorio de antes. Las fuentes nuevas vienen dentro de la página (licencia libre OFL), así que funcionan sin internet.":"Modern uses Outfit for text and Big Shoulders for titles: modern and easy to read. PES 6 Edit uses QuickExpress, the PES-style font. Retro uses Pixelify Sans and Silkscreen, pixel fonts inspired by the PlayStation 1 Winning Eleven games but still readable. Classic uses Tahoma, like old desktop programs. The new fonts are bundled in the page (free OFL license), so they work offline.",
