"Se armó un estudio para ver y editar los kits del kit-server del juego.":"A studio to view and edit the game's kit-server kits.",
"Se avanza con pases cortos y los jugadores se acercan para ofrecer opciones.":"Move up with short passes while players get close to offer options.",
"Se busca a los de arriba con pases largos para avanzar rápido.":"Long balls to the forwards to move up fast.",
"Se cierra el medio y se empuja al rival hacia las bandas.":"Close the middle and push the opponent out wide.",
"Se cierran las bandas y se empuja al rival hacia el medio.":"Close the flanks and push the opponent into the middle.",
"Se defiende atrás y se sale con pelotazos al espacio.":"Defend deep and break with long balls into space.",
"Se guardó, pero la verificación no coincide. Revisá el respaldo.":"Saved, but verification doesn't match. Check the backup.",
"Se marca muy de cerca al rival que recibe la pelota.":"Mark the opponent receiving the ball very tightly.",
"Se ordena tocando el título de cada columna, se filtra por texto, por posición (ARQ, DEF, MED, DEL) y por situación (titulares, banco, reserva, sin proteger). Hay tres densidades de filas, elección de columnas y exportación.":"Sort by clicking any column header, filter by text, by position (GK, DEF, MID, FWD) and by status (starters, bench, reserves, unprotected). There are three row densities, column picking and export.",
"Se perdería el plantel de {x} equipo(s) (ID {x}{x}).":"The squad of {x} team(s) would be lost (ID {x}{x}).",
"Se perderían {x} jugador(es) del original (ID {x}{x}).":"{x} player(s) from the original would be lost (ID {x}{x}).",
"Se presiona en campo rival para recuperar la pelota rápido. Exige mucha resistencia.":"Press in the opponent's half to win the ball back fast. Very demanding on stamina.",
"Se puede elegir un tipo de tela (lisa, malla, piqué, panal, acanalada, sarga, jacquard o algodón retro) y el relieve de los dibujos del kit. El editor genera el normal map que el juego aplica sobre la camiseta. El escudo con relieve depende de que el juego lo cargue.":"You can pick a fabric type (plain, mesh, piqué, honeycomb, ribbed, twill, jacquard or retro cotton) and the embossing of the kit's designs. The editor generates the normal map the game applies on the shirt. An embossed crest depends on the game loading it.",
"Se puede instalar como app":"Can be installed as an app",
"Se recupera y se sale rápido con pases cortos.":"Win it back and break fast with short passes.",
"Se revisó que no haya funciones repetidas ni sin uso, y se quitó la que abría carpetas con los botones viejos. El ícono de la pestaña también pasó a ser un archivo.":"Checked for duplicate or unused functions, and removed the one that opened folders with the old buttons. The tab icon is now a file too.",
"Se sacaron \"Abrir carpeta\" y \"Abrir archivo\" de la barra. Si el navegador no permite leer carpetas (Firefox o Safari), la pantalla de carga ofrece elegir el EDIT a mano.":"\"Open folder\" and \"Open file\" were removed from the bar. If your browser can't read folders (Firefox or Safari), the loading screen lets you pick the EDIT manually.",
"Se sacó \"Fluidez ahora\" del panel de Gráficos.":"\"Smoothness now\" was removed from the Graphics panel.",
"Se terminaron las consultas gratis de hoy (100 por día). Mañana se renuevan.":"Today's free requests are used up (100 per day). They reset tomorrow.",
