"Si avisa que la base no está cargada":"If it says the database isn't loaded",
"Si el editor te pide permiso para escribir en esa carpeta, aceptá: lo necesita para instalar el módulo.":"If the editor asks for permission to write to that folder, accept: it needs it to install the module.",
"Si el escudo no está en las carpetas del juego, se busca por nombre en TheSportsDB y queda guardado.":"If the crest isn't in the game folders, it's searched by name on TheSportsDB and saved.",
"Si el juego está abierto":"If the game is open",
"Si el sider.log muestra el error de una versión anterior del módulo, el aviso ya no manda a revisar la protección contra ransomware de Windows: explica qué pasó y que alcanza con repetir los pasos. Las líneas de ayuda que el módulo deja en el registro ya no se confunden con un error de permisos.":"If sider.log shows an error from an older version of the module, the warning no longer sends you to check Windows ransomware protection: it explains what happened and that repeating the steps is enough. The help lines the module leaves in the log are no longer mistaken for a permissions error.",
"Si es la primera vez, si el módulo se acaba de instalar o si en content\\edit21-db faltan archivos, el editor muestra qué hacer: abrir PES 2021 con Sider hasta el menú principal, entrar en Partido › Amistoso hasta la elección de equipos y cerrar el juego. Después, \"Ya lo hice\" vuelve a leer la base. También avisa al arrancar si la copia está incompleta.":"If it's the first time, the module was just installed or files are missing in content\\edit21-db, the editor shows what to do: open PES 2021 with Sider up to the main menu, go to Match › Friendly up to team selection and close the game. Then \"I did it\" re-reads the database. It also warns at startup if the copy is incomplete.",
"Si guardás ahora,":"If you save now,",
