"combina el puntaje de los últimos partidos (pesa más el más reciente y los minutos jugados), los goles y asistencias para su puesto, la campaña del equipo, la edad (los jóvenes suben más rápido, los veteranos bajan más rápido) y el valor de mercado (a los cracks se les exige más). Topes: hasta":"combines recent match ratings (the latest match and minutes played weigh more), goals and assists for their position, the team's season, age (young players rise faster, veterans drop faster) and market value (more is expected from stars). Caps: up to",
