"en sider.ini, que Sider ya trae): repetí los pasos de arriba.":"in sider.ini, which the game already includes): repeat the steps above.",
"en tu EDIT":"in your EDIT",
"en tu Sider: es la primera vez, así que la copia de la base todavía no existe.":"in your Sider: it's the first time, so the database copy doesn't exist yet.",
"en un suplente, elegí por qué titular entra. En cualquier jugador, elegí otro equipo para transferirlo: se suma con un dorsal libre.":"on a sub, choose which starter they replace. On any player, choose another team to transfer them: they join with a free shirt number.",
"encuadres rápidos (frente, espalda, costados, 3/4, desde arriba, primer plano del pecho), lente más abierta o más cerrada y giro automático con velocidad.":"quick angles (front, back, sides, 3/4, top, chest close-up), wider or narrower lens and auto-spin with adjustable speed.",
