"es una estimación por valoración, edad, potencial y liga. Tocalo para poner el valor real (por ejemplo el de Transfermarkt).":"it's an estimate based on rating, age, potential and league. Tap it to enter the real value (e.g. from Transfermarkt).",
"escribe directo en la carpeta del juego. El primer guardado de cada sesión crea un respaldo con la fecha.":"writes straight to the game folder. The first save of each session creates a dated backup.",
"escribe el brillo en el alfa de la textura del kit a resolución completa, sin tocar los colores.":"writes the shine to the kit texture's alpha at full resolution, without touching the colors.",
"escribe el config.txt (con copia la primera vez). Las texturas se guardan apenas las subís o generás. Hay que volver a abrir el juego para verlo.":"writes config.txt (with a backup the first time). Textures are saved as soon as you upload or generate them. Restart the game to see it.",
"escribilo en la casilla. Si dos jugadores quedan con el mismo número aparece un aviso y el botón \"Arreglar dorsales repetidos\".":"type it in the box. If two players end up with the same number, a warning appears with a \"Fix duplicate numbers\" button.",
"escribí parte del nombre, el ID, el dorsal o el país. Los botones ARQ / DEF / MED / DEL y Titulares / Banco / Reserva / Sin proteger se suman al texto.":"type part of the name, the ID, shirt number or country. The GK / DEF / MID / FWD and Starters / Bench / Reserves / Unprotected buttons combine with the text.",
