"Al tocar \"Conectar carpeta Sider\", el editor revisa tu Sider: si falta el módulo lo copia a modules\\, agrega la línea lua.module = \"edit21_db.lua\" en sider.ini (guardando una copia de seguridad como sider.ini.bak-pes-editor) y crea la carpeta content\\edit21-db. Si ya está pero es una versión vieja, lo actualiza. Es un módulo de solo lectura: no cambia nada del juego.":"When you tap \"Connect Sider folder\", the editor checks your Sider: if the module is missing it copies it to modules\\, adds the line lua.module = \"edit21_db.lua\" to sider.ini (saving a backup as sider.ini.bak-pes-editor) and creates the folder content\\edit21-db. If it is there but outdated, it updates it. It is a read-only module: it changes nothing in the game.",
"Arreglo del módulo edit21_db.lua (en algunas instalaciones Sider no deja que los módulos guarden archivos), planteles de la base verificados con los archivos reales del juego y un lugar mejor para el video de YouTube.":"Fix for the edit21_db.lua module (on some installs Sider does not let modules save files), database squads checked against the real game files, and a better spot for the YouTube video.",
