"Borrar caché":"Clear cache",
"Si algo se ve viejo o raro, borrá la caché: el editor se recarga con la última versión. Tus ajustes y el EDIT no se tocan.":"If something looks old or odd, clear the cache: the editor reloads with the latest version. Your settings and the EDIT are not touched.",
