"Los demás tamaños salen de la imagen más grande.":"The other sizes come from the largest image.",
"({x} con otro ID: se guardan con el {x})":"({1} with another ID: saved as {2})",
"Este equipo usa un escudo hecho en el modo Editar del juego, que tapa al de la carpeta Sider.":"This team uses a crest made in the game's Edit mode, which hides the Sider one.",
