"{x}% min.":"{x}% min.",
"Duda":"Doubtful",
"Lesionado":"Injured",
"Ausente":"Absent",
"Era habitual y faltó a las últimas {x} citaciones":"Was a regular and missed the last {x} squads",
"Era habitual y faltó a las últimas {x} citaciones.":"Was a regular and missed the last {x} squads.",
"Cómo se calcula la forma de este jugador":"How this player's form is calculated",
"Cómo se calcula la forma de":"How form is calculated for",
"Forma:":"Form:",
"compara lo que se espera de cada jugador con lo que está haciendo en la realidad. Cada parte suma o resta puntos de valoración; el total se redondea y tiene tope. Con ⓘ se ve el detalle de cada jugador con sus números.":"compares what is expected of each player with what they are actually doing. Each part adds or subtracts rating points; the total is rounded and capped. ⓘ shows each player's breakdown with their numbers.",
"📈 Últimos partidos:":"📈 Recent matches:",
"el puntaje de cada partido (lo calcula el editor con goles, asistencias, tiros, atajadas, tarjetas y resultado) contra lo que se le exige. Pesan más el partido más reciente y los minutos jugados.":"each match rating (the editor computes it from goals, assists, shots, saves, cards and the result) against what is expected. The most recent match and minutes played weigh more.",
"🗓 Temporada completa:":"🗓 Whole season:",
"su puntaje promedio en todos los partidos analizados y qué parte de los minutos posibles juega: el titular fijo suma, el que casi no juega resta.":"their average rating across every analyzed match and the share of available minutes they play: the regular starter gains, the one who barely plays loses.",
"⚽ Goles y asistencias:":"⚽ Goals and assists:",
"cada 90 minutos, contra lo normal para su puesto (un defensor que hace goles suma más que un delantero). Se usa la temporada si ya tiene 270 minutos; si no, los últimos partidos.":"per 90 minutes, against what is normal for their position (a scoring defender gains more than a forward). The season is used once they have 270 minutes; otherwise, the recent matches.",
"🏟 Equipo:":"🏟 Team:",
"los puntos por partido de la campaña y si el equipo mejoró o empeoró respecto de la temporada anterior.":"the season's points per match and whether the team improved or got worse compared with the previous season.",
"📚 Historial:":"📚 History:",
"sus temporadas anteriores moderan la actual (una racha de tres partidos no lo vuelve crack, ni un mal mes lo hunde) y premian al titular de siempre.":"their previous seasons temper the current one (a three-match streak doesn't make a star, nor does a bad month sink them) and reward the long-time starter.",
"🤕 Lesiones y ausencias:":"🤕 Injuries and absences:",
"lesionado −1 (−1,5 si lleva más de dos meses), en duda −0,5; el habitual que faltó a las últimas tres citaciones, −1.":"injured −1 (−1.5 if out for over two months), doubtful −0.5; a regular who missed the last three squads, −1.",
"🎂 Edad:":"🎂 Age:",
"multiplica el total: hasta 21 años sube ×1,3 y baja ×0,9; de 30 a 32 sube ×0,8 y baja ×1,15; de 33 sube ×0,6 y baja ×1,3. Topes: hasta +4 en jóvenes, +3 en general, +2 en mayores de 33; hasta -3 (-4 en veteranos).":"multiplies the total: up to 21 rises ×1.3 and drops ×0.9; 30 to 32 rises ×0.8 and drops ×1.15; 33 and over rises ×0.6 and drops ×1.3. Caps: up to +4 for young players, +3 in general, +2 over 33; down to -3 (-4 for veterans).",
"⭐ Exigencia:":"⭐ Expectation:",
"a los cracks se les pide más: el puntaje esperado sube con la valoración del juego y con el valor de mercado.":"more is asked of stars: the expected rating rises with the patch rating and the market value.",
"Fuentes:":"Sources:",
"con ESPN entran los últimos 6 partidos, toda la temporada, el plantel con sus lesionados, la campaña anterior y el historial de cada jugador (se guarda 7 días). Con API-Football solo entran los últimos partidos.":"with ESPN you get the last 6 matches, the whole season, the squad with its injured players, the previous season's record and each player's history (kept for 7 days). With API-Football only the recent matches count.",
