"Próximamente":"Coming soon",
"Valoración dinámica con datos reales":"Dynamic rating with real data",
"La forma de cada jugador ahora usa toda la temporada, los goleadores, las lesiones y el historial de ESPN. Está en prueba: si ves un dato raro, avisá.":"Each player's form now uses the whole season, top scorers, injuries and history from ESPN. It's being tested: if you see odd data, let us know.",
"Más estilos gráficos":"More graphics styles",
"Modos inspirados en los menús de otras ediciones de PES, como el de PES 5.":"Modes inspired by the menus of other PES editions, like PES 5.",
"Habilidades desde la ficha":"Skills from the player card",
"Editar las habilidades de cada jugador desde su ficha, con los nombres del juego.":"Edit each player's skills from their card, with the game's names.",
"Formaciones como plantillas":"Formations as templates",
"Guardar y compartir tus formaciones favoritas.":"Save and share your favourite formations.",
"Comparar planteles":"Compare squads",
"Ver dos planteles lado a lado antes de un traspaso.":"See two squads side by side before a transfer.",
"Son cosas en camino: el orden y los detalles pueden cambiar.":"These are on the way: the order and details may change.",
"Ver novedades":"See what's new",
"La valoración por rendimiento ahora mira toda la temporada, los goleadores, las lesiones y el historial de cada jugador, y te muestra de dónde sale cada punto.":"The performance rating now looks at the whole season, top scorers, injuries and each player's history, and shows you where every point comes from.",
"Búsqueda que encuentra a tu equipo":"A search that finds your team",
"\"Como 1907\" ahora encuentra a \"Como\": el editor prueba el nombre sin el año, sin siglas como FC, Club o Calcio y con la palabra más importante, y usa el país del equipo en tu EDIT para elegir bien.":"\"Como 1907\" now finds \"Como\": the editor tries the name without the year, without abbreviations like FC, Club or Calcio and with the main word, and uses the team's country in your EDIT to pick the right one.",
"Toda la temporada, no solo 6 partidos":"The whole season, not just 6 matches",
"Con ESPN, el editor analiza en segundo plano todos los partidos de la temporada: goleadores, asistencias, minutos y puntaje de cada jugador. También trae la campaña de la temporada anterior.":"With ESPN, the editor analyzes every match of the season in the background: top scorers, assists, minutes and each player's rating. It also fetches the previous season's record.",
"Tocá \"⚽ Últimos partidos reales\" con la fuente ESPN.":"Tap \"⚽ Latest real matches\" with the ESPN source.",
"Dejá marcado \"Analizar toda la temporada\" y esperá a que termine.":"Leave \"Analyze the whole season\" ticked and wait for it to finish.",
"Lesionados y ausentes":"Injured and absent players",
"El plantel de ESPN dice quién está lesionado o en duda. El lesionado baja su forma (más si lleva más de dos meses afuera), y también el habitual que faltó a las últimas 3 citaciones.":"The ESPN squad says who is injured or doubtful. An injured player's form drops (more after two months out), and so does a regular who missed the last 3 squads.",
"Historial de cada jugador":"Each player's history",
"Las temporadas anteriores de cada jugador moderan la forma: una racha corta no lo vuelve crack, un mal mes no lo hunde y el titular de siempre suma.":"Each player's previous seasons temper the form: a short streak doesn't make a star, a bad month doesn't sink anyone, and the long-time starter gains.",
"Cómo se calcula, jugador por jugador":"How it is calculated, player by player",
"En Forma del plantel cada jugador tiene un botón ⓘ con el detalle: cada parte de la forma con sus números, la edad y los topes. La ayuda \"Cómo se calcula la forma\" explica la fórmula completa.":"In Squad form every player has an ⓘ button with the breakdown: each part of the form with its numbers, age and caps. The \"How form is calculated\" help explains the whole formula.",
"Abrí \"📊 Forma del plantel\".":"Open \"📊 Squad form\".",
"Tocá ⓘ al lado de un jugador.":"Tap ⓘ next to a player.",
"Un cartel muestra lo que está en prueba y lo que viene. También queda arriba de todo en Novedades.":"A notice shows what is being tested and what is coming. It also stays at the top of What's new.",
"\"Como 1907\" ya encuentra a \"Como\" en ESPN.":"\"Como 1907\" now finds \"Como\" on ESPN.",
"la forma de cada jugador mira toda la temporada, las lesiones y su historial.":"each player's form looks at the whole season, injuries and their history.",
"tocá ⓘ en Forma del plantel para ver de dónde sale cada punto.":"tap ⓘ in Squad form to see where every point comes from.",
"un cartel muestra lo que está en desarrollo.":"a notice shows what is in development.",
