"Los videos se ven chiquitos arriba del reproductor (YouTube no permite ocultarlos ni sacarles el audio).":"Videos show small above the player (YouTube doesn't allow hiding them or taking out their audio).",
"Pegá el link de un video o una lista de YouTube. Para buscar por nombre desde la web, agregá tu clave de YouTube en \"Claves para buscar\" (en la app para Windows no hace falta).":"Paste the link to a YouTube video or playlist. To search by name on the web, add your YouTube key under \"Search keys\" (not needed in the Windows app).",
"Con Spotify Premium iniciado en este navegador los temas suenan completos; si no, Spotify da 30 segundos de cada uno.":"With Spotify Premium signed in on this browser, tracks play in full; otherwise Spotify gives 30 seconds of each.",
"Pegá el link de un tema, disco o lista de Spotify. Para buscar por nombre, conectá tu cuenta en \"Claves para buscar\".":"Paste the link to a Spotify track, album or playlist. To search by name, connect your account under \"Search keys\".",
