"Disco":"Album",
"Lista":"Playlist",
"{x} temas":"{1} tracks",
"Suele estar en Documentos\\KONAMI\\eFootball PES 2021 SEASON UPDATE\\<número>\\drmp (o \\save; sin Steam, como CPY, directo en \\save). Si nunca guardaste en el modo Editar del juego, el archivo todavía no existe.":"It's usually in Documents\\KONAMI\\eFootball PES 2021 SEASON UPDATE\\<number>\\drmp (or \\save; without Steam, like CPY, straight in \\save). If you never saved in the game's Edit mode, the file doesn't exist yet.",
"; en Football Life, la carpeta del juego). Se hace una sola vez: después el editor la recuerda.":"; in Football Life, the game folder). You only do this once: after that the editor remembers it.",
"En esa carpeta no está Sider (sider.exe o sider.ini). Elegí la carpeta de Sider de tu juego; en Football Life es la carpeta del juego.":"Sider isn't in that folder (sider.exe or sider.ini). Pick your game's Sider folder; in Football Life it's the game folder.",
"Sider conectado (sin kit-server: los kits no se pueden editar acá){x}{x}{x}.":"Sider connected (no kit-server: kits can't be edited here){1}{2}{3}.",
"Tu Sider no tiene kit-server (content\\kit-server\\map.txt): los kits de este juego no se pueden editar acá.":"Your Sider has no kit-server (content\\kit-server\\map.txt): this patch's kits can't be edited here.",
"Cargando escudos y fotos…":"Loading crests and photos…",
"Cargando escudos y fotos… {x} de {x}":"Loading crests and photos… {1} of {2}",
"Entrar ya (el resto carga después)":"Go in now (the rest loads later)",
"Escudos y fotos: el resto termina de cargar en el editor.":"Crests and photos: the rest finishes loading in the editor.",
"Escudos y fotos listos.":"Crests and photos ready.",
"La primera vez tarda más porque busca escudos y fotos en internet. Después quedan guardados y la carga es rápida.":"The first time takes longer because it looks up crests and photos online. After that they are saved and loading is quick.",
"Tu carpeta Sider: qué mods y módulos tiene, y edición fácil de sider.ini":"Your Sider folder: which mods and modules it has, and easy sider.ini editing",
"Sider es el programa que carga los mods en el juego. Conectá tu carpeta Sider y acá vas a ver qué mods tiene (escudos, caras, kits, estadios…), qué módulos corre y vas a poder ordenar y prender o apagar cada cosa en sider.ini sin tocar el texto a mano.":"Sider is the program that loads the game into the game. Connect your Sider folder and here you'll see which mods it has (crests, faces, kits, stadiums…), which modules it runs, and you'll be able to reorder and turn each thing on or off in sider.ini without touching the text by hand.",
"Elegí la carpeta de Sider de tu juego (la que tiene sider.exe; en Football Life, la carpeta del juego).":"Pick your game's Sider folder (the one with sider.exe; in Football Life, the game folder).",
"Hace falta tu permiso para volver a leer la carpeta":"Your permission is needed to read the folder again",
"Permitir leer la carpeta Sider":"Allow reading the Sider folder",
"No hay sider.ini en":"There is no sider.ini in",
". Si tu Sider nunca se abrió, abrilo una vez para que lo cree; si no, elegí la carpeta que tiene sider.exe.":". If your Sider has never been opened, open it once so it creates the file; otherwise pick the folder that has sider.exe.",
