"Activar":"Enable",
"Carpetas de contenido":"Content folders",
"Carpeta content":"content folder",
"Ajustes de Sider":"Sider settings",
"Cada carpeta trae archivos del juego cambiados (escudos, caras, kits, estadios…). El orden importa: si dos carpetas tienen el mismo archivo,":"Each folder brings changed game files (crests, faces, kits, stadiums…). Order matters: if two folders have the same file,",
"manda la de más arriba":"the one higher up wins",
"No hay líneas cpk.root en sider.ini.":"There are no cpk.root lines in sider.ini.",
"Los módulos agregan funciones a Sider: el kit server carga los kits desde content, edit21_db le da al editor la base del juego, otros ponen marcadores, cantos o estadios. También se cargan en orden.":"Modules add features to Sider: the kit server loads kits from content, edit21_db gives the editor the game database, others add scoreboards, chants or stadiums. They also load in order.",
"No hay líneas lua.module en sider.ini.":"There are no lua.module lines in sider.ini.",
"Acá dejan sus archivos los módulos. El editor usa":"This is where modules keep their files. The editor uses",
"(los kits) y":"(the kits) and",
"(la copia de la base del juego); las caras y los escudos salen de las carpetas de arriba.":"(the copy of the game database); faces and crests come from the folders above.",
"Línea quitada. No se borra del archivo hasta que toques Guardar.":"Line removed. Nothing is deleted from the file until you tap Save.",
"Ojo: lua.enabled está en 0, los módulos no corren. Arriba hay un botón para activarlo.":"Heads up: lua.enabled is 0, so modules don't run. There is a button above to enable it.",
"Hay cambios sin guardar. ¿Volver a leer el archivo y perderlos?":"There are unsaved changes. Read the file again and lose them?",
"Texto aplicado. Tocá Guardar para escribirlo en sider.ini.":"Text applied. Tap Save to write it to sider.ini.",
"El texto es igual al archivo.":"The text is the same as the file.",
"Copia de seguridad cargada: revisala y tocá Guardar para dejarla como sider.ini.":"Backup loaded: check it and tap Save to make it your sider.ini.",
"Sin permiso para escribir en la carpeta Sider.":"No permission to write to the Sider folder.",
"No se pudo guardar sider.ini: {x}":"Couldn't save sider.ini: {1}",
"sider.ini guardado (copia en sider.ini.bak-pes-editor). Abrí el juego de nuevo con Sider para que tome los cambios.":"sider.ini saved (backup in sider.ini.bak-pes-editor). Open the game again with Sider so it picks up the changes.",
"la pestaña Sider":"the Sider tab",
"Sider es el programa que carga los mods en el juego. Todo sale de sider.ini: cada cpk.root es una carpeta con archivos del juego cambiados (escudos, caras, kits, estadios…) y cada lua.module es un módulo que agrega funciones (kit server, caras desde content, marcadores…).":"Sider is the program that loads the game into the game. Everything comes from sider.ini: each cpk.root is a folder with changed game files (crests, faces, kits, stadiums…) and each lua.module is a module that adds features (kit server, faces from content, scoreboards…).",
"Qué muestra":"What it shows",
"las líneas cpk.root en el orden en que las usa el juego: si dos carpetas tienen el mismo archivo, manda la de más arriba. El editor mira adentro de cada una y dice qué trae (escudos, fotos, kits…) y, si el editor la usa, para qué.":"the cpk.root lines in the order the game uses them: if two folders have the same file, the one higher up wins. The editor looks inside each one and says what it brings (crests, photos, kits…) and, if the editor uses it, what for.",
"las líneas lua.module. De cada uno dice qué hace (si lo conoce) y qué carpeta de content usa, y avisa si el archivo falta en modules.":"the lua.module lines. For each one it says what it does (if it knows it) and which content folder it uses, and warns if the file is missing from modules.",
"lo que usan los módulos: kit-server (los kits, que el editor edita en Equipos › Kits), edit21-db (la copia de la base para el editor), caras, cantos…":"what the modules use: kit-server (the kits, which the editor edits in Teams › Kits), edit21-db (the database copy for the editor), faces, chants…",
"los interruptores de Sider explicados en castellano: livecpk, módulos, overlay, cámara, barras negras… Lo que no está en tu archivo aparece como \"por defecto\".":"Sider's switches explained in plain words: livecpk, modules, overlay, camera, black bars… Whatever isn't in your file shows as \"default\".",
"Editar sider.ini":"Editing sider.ini",
"Prender o apagar":"Turn on or off",
"el interruptor de cada línea la comenta (;) o la descomenta: no se borra nada.":"each line's switch comments it out (;) or uncomments it: nothing is deleted.",
"las flechas suben o bajan la carpeta o el módulo. La primera carpeta manda.":"the arrows move the folder or module up or down. The first folder wins.",
"las carpetas de livecpk y los módulos de modules que no están en sider.ini aparecen abajo de cada lista con un botón para agregarlos.":"the livecpk folders and the modules files that aren't in sider.ini show up below each list with a button to add them.",
"nada se escribe hasta que tocás Guardar sider.ini. La primera vez queda una copia en sider.ini.bak-pes-editor, que podés volver a cargar desde el texto. Después abrí el juego de nuevo con Sider para que tome los cambios.":"nothing is written until you tap Save sider.ini. The first time a copy is kept as sider.ini.bak-pes-editor, which you can load again from the text view. Then open the game again with Sider so it picks up the changes.",
"Texto completo":"Full text",
