"En esa carpeta no está Sider (sider.exe o sider.ini) ni en sus subcarpetas. Adentro hay: {x}. Elegí la carpeta de Sider de tu juego; en Football Life es la carpeta del juego.":"Sider (sider.exe or sider.ini) isn't in that folder or its subfolders. Inside there is: {1}. Pick your game's Sider folder; in Football Life it's the game folder.",
"En esa carpeta no está Sider (sider.exe o sider.ini) ni en sus subcarpetas. Adentro hay {x} carpetas, como {x}. Elegí la carpeta de Sider de tu juego; en Football Life es la carpeta del juego.":"Sider (sider.exe or sider.ini) isn't in that folder or its subfolders. Inside there are {1} folders, such as {2}. Pick your game's Sider folder; in Football Life it's the game folder.",
