"No reconozco qué trae: mirá las carpetas de adentro.":"I don't recognise what it brings: look at the folders inside.",
"Por el nombre, parece:":"Judging by the name, it looks like:",
"Módulo que no conozco: abrí el .lua para ver qué hace.":"A module I don't know: open the .lua to see what it does.",
"Carpeta agregada al final de cpk.root (la de menos prioridad). Subila con las flechas si hace falta y después tocá Guardar.":"Folder added at the end of cpk.root (lowest priority). Move it up with the arrows if needed, then tap Save.",
"Módulo agregado al final. Ojo: lua.enabled está en 0, los módulos no corren; arriba hay un botón para activarlo.":"Module added at the end. Heads up: lua.enabled is 0, so modules don't run; there is a button above to enable it.",
"Módulo agregado al final de lua.module. Tocá Guardar cuando termines.":"Module added at the end of lua.module. Tap Save when you're done.",
"📂 Buscar EDIT":"📂 Find EDIT",
