"Buscar el EDIT":"Find the EDIT",
"EDIT encontrados (el juego usa el que guardó por última vez):":"EDITs found (the game uses the one it saved last):",
"Todavía no hay una carpeta del juego conectada.":"No game folder is connected yet.",
