"📁 Elegir la carpeta del EDIT…":"📁 Choose the EDIT folder…",
"📄 Abrir el archivo a mano (se guarda como copia)":"📄 Open the file by hand (saved as a copy)",
"PES 2021 de Steam: Documentos\\KONAMI\\eFootball PES 2021 SEASON UPDATE\\<número>\\drmp. Football Life: la misma carpeta, en":"PES 2021 on Steam: Documents\\KONAMI\\eFootball PES 2021 SEASON UPDATE\\<number>\\drmp. Football Life: the same folder, in",
". Podés elegir Documentos o directo la carpeta donde está el EDIT00000000.":". You can choose Documents or the folder that holds EDIT00000000 directly.",
