"Promedio":"Average",
"Qué tan rápido lee el juego para atacar: se desmarca, busca el espacio y pica al vacío cuando su equipo tiene la pelota. Clave en delanteros.":"How quickly he reads the game in attack: losing his marker, finding space and making runs in behind when his team has the ball. Key for forwards.",
"Precisión de los remates con el pie. Con más nivel la pelota va más cerca de donde apuntás.":"Accuracy of shots with the foot. The higher it is, the closer the ball goes to where you aim.",
"Precisión de los cabezazos, tanto para rematar al arco como para pasarla.":"Accuracy of headers, both for shooting at goal and for passing.",
"Fuerza con la que le pega a la pelota: remates más potentes y desde más lejos.":"How hard he strikes the ball: more powerful shots, and from further out.",
"Precisión en las jugadas con pelota quieta: tiros libres, córners y penales.":"Accuracy from set pieces: free kicks, corners and penalties.",
"Cuánta comba le puede dar a la pelota en centros, pases y remates.":"How much curl he can put on the ball in crosses, passes and shots.",
"Calidad del primer toque y del manejo en general: recibir, girar y proteger la pelota sin perderla.":"Quality of the first touch and general ball handling: receiving, turning and shielding the ball without losing it.",
"Habilidad para llevar la pelota pegada al pie corriendo rápido y para encarar al rival.":"Ability to keep the ball close while running fast and to take on defenders.",
"Manejo de la pelota en espacios chicos y a poca velocidad: giros cortos y cambios de dirección con marca encima.":"Ball handling in tight spaces at low speed: quick turns and changes of direction under pressure.",
"Precisión de los pases por abajo, cortos y largos.":"Accuracy of passes along the ground, short and long.",
"Precisión de los pases altos, cambios de frente y centros.":"Accuracy of lofted passes, switches of play and crosses.",
"Velocidad máxima corriendo, con o sin la pelota.":"Top running speed, with or without the ball.",
"Qué tan rápido llega a su velocidad máxima en los primeros metros. Sirve para ganar el pique y arrancar desde parado.":"How quickly he reaches top speed over the first few metres. Helps win sprints and burst away from a standstill.",
"Equilibrio para no caerse ni perder la pelota en giros bruscos o cuando lo tocan.":"Balance to stay on his feet and keep the ball in sharp turns or under contact.",
"Fuerza para aguantar cargas y empujones y ganar los choques cuerpo a cuerpo.":"Strength to hold off challenges and shoves and win physical duels.",
"Altura que alcanza al saltar. Importa en los cabezazos y en las pelotas divididas por arriba.":"How high he jumps. Matters for headers and aerial duels.",
"Cuánto aguanta corriendo durante el partido antes de cansarse. Con poca, rinde menos en el segundo tiempo.":"How long he can keep running before tiring. With little of it he drops off in the second half.",
"Qué tan rápido reacciona cuando ataca el rival: marca, cierra espacios y se ubica para cortar pases.":"How quickly he reacts when the opponent attacks: marking, closing space and positioning to cut out passes.",
"Capacidad para sacarle la pelota al rival con entradas y quites.":"Ability to win the ball back with tackles and steals.",
"Qué tan encima del rival juega para presionar y disputar la pelota. Mucha también puede traer más faltas.":"How tightly he presses and contests the ball. A lot of it can also mean more fouls.",
"Lectura y ubicación del arquero: qué tan rápido reacciona ante los remates y cuándo sale a cortar.":"The keeper's reading and positioning: how fast he reacts to shots and when he comes off his line.",
"Capacidad del arquero para quedarse con la pelota en las manos en vez de dar rebote.":"The keeper's ability to hold on to the ball instead of parrying it.",
"Calidad de los despejes con los puños: qué tan lejos y hacia dónde manda la pelota.":"Quality of punched clearances: how far and where he sends the ball.",
"Velocidad de reacción del arquero para atajar remates desde cerca.":"The keeper's reaction speed to stop close-range shots.",
"Cuánto del arco cubre el arquero al estirarse para llegar a los remates.":"How much of the goal the keeper covers when stretching to reach shots.",
"Qué tan seguido usa la pierna menos hábil. En 1 casi nunca la usa; en 4 la usa sin problema.":"How often he uses his weaker foot. At 1 he almost never does; at 4 he uses it freely.",
"Qué tan precisos son los pases y remates con la pierna menos hábil.":"How accurate passes and shots are with his weaker foot.",
